DROP TABLE IF EXISTS `expenses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expenses` (
  `expense_id` int NOT NULL AUTO_INCREMENT,
  `Partner` varchar(255) DEFAULT NULL,
  `partner_id` int DEFAULT NULL,
  `FileName` varchar(255) NOT NULL,
  `Category` varchar(100) DEFAULT NULL,
  `WorkPackage` varchar(50) DEFAULT NULL,
  `Currency` varchar(10) DEFAULT 'EUR',
  `Amount` decimal(15,2) DEFAULT NULL,
  `ShortDescription` text,
  `Date` date DEFAULT NULL,
  `uploaded_by` int DEFAULT NULL COMMENT 'user_id of uploader',
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `rejection_comments` text,
  `approved_by` int DEFAULT NULL COMMENT 'user_id of approver',
  `approver_signature_name` varchar(255) DEFAULT NULL,
  `approver_signature_position` varchar(255) DEFAULT NULL,
  `approver_signature_organization` varchar(255) DEFAULT NULL,
  `approver_signature_file` varchar(255) DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `approval_comments` text,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`expense_id`),
  KEY `partner_id` (`partner_id`),
  KEY `uploaded_by` (`uploaded_by`),
  KEY `approved_by` (`approved_by`),
  KEY `idx_expenses_status` (`status`),
  KEY `idx_expenses_month_year` (`partner_id`),
  CONSTRAINT `expenses_ibfk_1` FOREIGN KEY (`partner_id`) REFERENCES `partners` (`partner_id`) ON DELETE SET NULL,
  CONSTRAINT `expenses_ibfk_2` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `expenses_ibfk_3` FOREIGN KEY (`approved_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

